{
  "up": "Select molecule_chembl_id as compound_chembl_id, canonical_smiles, compound_key, pubmed_id as pubmed_id_or_doi, assays.description as assay_description, activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units, activities.activity_comment, target_dictionary.chembl_id as target_chembl_id, target_dictionary.pref_name as target_name, target_dictionary.organism as target_organism From activities Join assays On activities.assay_id = assays.assay_id Join target_dictionary On assays.tid = target_dictionary.tid Join molecule_dictionary On activities.molregno = molecule_dictionary.molregno Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where activities.standard_type = 'IC50' And activities.standard_relation = '=' And activities.standard_units = 'nM' And target_dictionary.pref_name = 'Cytochrome P450 2C19' And (activities.pubmed_id Is Not Null Or activities.doi Is Not Null) Order By compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism"
}
